-- Export every non-English printing row from the LOCAL db to CSV (stdout).
-- Explicit column list (57 cols) so import maps by name, not position.
\copy (SELECT "printing_id","card_unique_id","set_printing_unique_id","collector_number","set","edition","foiling","rarity","is_first_edition","is_unlimited","is_normal_edition","is_normal_foil","is_rainbow_foil","is_cold_foil","is_extended_art","is_common","is_rare","is_super_rare","is_majestic","is_legendary","is_fabled","is_promo","image_url","image_rotation_degrees","artists","flavor_text","art_variations","tcgplayer_product_id","tcgplayer_url","tcgplayer_subtype_name","tcg_market","tcg_low","tcg_mid","tcg_high","has_price","price_updated_at","is_budget","is_under_5","is_under_10","is_under_25","is_under_50","is_under_100","is_expensive","is_premium","expansion_slot","content_hash","created_at","updated_at","other_face_printing_id","is_front_face","foil_inset_top","foil_inset_right","foil_inset_bottom","foil_inset_left","foil_inset_round","foil_inset_locked","language" FROM printings WHERE language <> 'en') TO STDOUT WITH (FORMAT csv, HEADER true)
